import { useState, FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

const ROLE_OPTIONS = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeamMemberForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [success, setSuccess] = useState(false);

  const isEmailValid = email.length > 0 && EMAIL_PATTERN.test(email);
  const emailError = email.length > 0 && !isEmailValid ? 'Укажите корректный адрес почты' : undefined;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isEmailValid) return;
    setSuccess(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)', maxWidth: 420 }}>
      {success && (
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 'var(--jx-r-sm)' }}>
          <div style={{ flex: 1 }}>
            <JxAlert intent="success" title="Приглашение отправлено">
              Мы отправили приглашение на {email}.
            </JxAlert>
          </div>
          <JxButton
            variant="ghost"
            size="sm"
            iconOnly
            aria-label="Закрыть сообщение"
            onClick={() => setSuccess(false)}
          >
            ×
          </JxButton>
        </div>
      )}

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          helperText="На этот адрес придёт приглашение в команду"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailError}
        />

        <JxSelect
          label="Роль"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление о приглашении"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton variant="primary" type="submit" disabled={!isEmailValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

